// Optional transactional mail. Disabled unless the owner binds both explicit gates.
// No delivery data, errors, contacts or tokens enter public signup responses/logs.
const WELCOME_SUBJECT = 'Thanks for signing up for the interest list';
const WELCOME_COPY = `Thanks for signing up for the Humanity Infrastructure interest list.

We'll send you a short, occasional letter about tools for human flourishing and the people building them.

Follow Jacob on X:
https://x.com/jacobcole4000

Explore the Ideaflow apps:
https://index.ideaflow.app

Build your own app in the Ideaflow ecosystem.
Own your mind. Own your networks.

You received this because you signed up at humanityinfrastructure.com.
Unsubscribe any time: {{unsubscribe_url}}

--
Humanity Infrastructure
https://humanityinfrastructure.com`;
function welcomeEnabled(env, ctx, origin) {
  return origin === 'https://humanityinfrastructure.com' && typeof ctx?.waitUntil === 'function' && env.WELCOME_EMAIL_ENABLED === 'true' && typeof env.HI_RESEND_API_KEY === 'string' && !!env.HI_RESEND_API_KEY;
}
function welcomeStatement(env, id) {
  // The randomly proposed ID matches only a newly inserted signup, never a duplicate.
  return env.SIGNUPS.prepare("INSERT INTO welcome_deliveries (signup_id,created_at,status,attempts) SELECT id,?,'pending',0 FROM signups WHERE id=? AND unsubscribed_at IS NULL ON CONFLICT(signup_id) DO NOTHING").bind(new Date().toISOString(),id);
}
function scheduleWelcome(env, ctx, id) {
  // Keep provider latency/failure off the public response path.
  try { ctx.waitUntil(deliverWelcome(env,id).catch(()=>{})); } catch { /* Optional mail never blocks signup. */ }
}
async function deliverWelcome(env,id) {
  // Two bounded attempts with the SAME provider idempotency key. A failure stays private.
  for(let attempt=0;attempt<2;attempt++) {
    const claimed=await env.SIGNUPS.prepare("UPDATE welcome_deliveries SET status='sending',attempts=attempts+1 WHERE signup_id=? AND status IN ('pending','retry') AND attempts<2 RETURNING signup_id").bind(id).first();
    if(!claimed)return;
    const row=await env.SIGNUPS.prepare('SELECT email,unsubscribe_token,unsubscribed_at FROM signups WHERE id=?').bind(id).first();
    if(!row || row.unsubscribed_at) {
      await env.SIGNUPS.prepare("UPDATE welcome_deliveries SET status='cancelled' WHERE signup_id=?").bind(id).run();return;
    }
    const unsubscribe='https://humanityinfrastructure.com/unsubscribe?t='+row.unsubscribe_token;
    const text=WELCOME_COPY.replace('{{unsubscribe_url}}',unsubscribe);
    try {
      const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.HI_RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':'hi-welcome-'+id},body:JSON.stringify({from:'Humanity Infrastructure <noreply@id.ideaflow.app>',to:[row.email],subject:WELCOME_SUBJECT,text,headers:{'List-Unsubscribe':'<'+unsubscribe+'>'}}),signal:AbortSignal.timeout(8000)});
      if(response.ok) {
        await env.SIGNUPS.prepare("UPDATE welcome_deliveries SET status='sent',sent_at=? WHERE signup_id=?").bind(new Date().toISOString(),id).run();return;
      }
      // Do not retry rejected addresses/keys/payloads; retry only transient failures.
      const retry=response.status===429 || response.status>=500;
      await env.SIGNUPS.prepare('UPDATE welcome_deliveries SET status=? WHERE signup_id=?').bind(retry && attempt===0?'retry':'failed',id).run();
      if(!retry)return;
    } catch {
      await env.SIGNUPS.prepare('UPDATE welcome_deliveries SET status=? WHERE signup_id=?').bind(attempt===0?'retry':'failed',id).run();
    }
  }
}

// Private signup routes. No personal data is published to WIT or public APIs.
const PRIVATE_HEADERS = { 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer', 'X-Content-Type-Options': 'nosniff' };
function signupResponse(body, status = 200, extra = {}) {
  return new Response(JSON.stringify(body), { status, headers: { ...PRIVATE_HEADERS, 'Content-Type': 'application/json', ...extra } });
}
function signupCsv(value) {
  const text = String(value ?? '');
  return '"' + (/^[\s]*[=+@\-]/.test(text) ? "'" : '') + text.replaceAll('"', '""') + '"';
}
async function signupHash(value) {
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value))), b => b.toString(16).padStart(2, '0')).join('');
}
async function handleSignup(request, env, ctx) {
  const url = new URL(request.url);
  if (!['/api/signup', '/unsubscribe', '/admin/signups.csv'].includes(url.pathname)) return null;
  try {
    if (url.pathname === '/admin/signups.csv') {
      if (request.method !== 'GET') return signupResponse({ error: 'Method not allowed' }, 405);
      const supplied = request.headers.get('Authorization') || '';
      if (!env.ADMIN_EXPORT_TOKEN || await signupHash(supplied) !== await signupHash('Bearer ' + env.ADMIN_EXPORT_TOKEN)) return signupResponse({ error: 'Unauthorized' }, 401);
      const rows = await env.SIGNUPS.prepare('SELECT * FROM signups ORDER BY consent_at').all();
      const columns = ['id','email','interest','handle','public_opt_in','consent_at','source_page','utm','referrer','unsubscribed_at','unsubscribe_url'];
      const csv = [columns.join(','), ...rows.results.map(row => columns.map(key => signupCsv(key === 'unsubscribe_url' ? url.origin + '/unsubscribe?t=' + row.unsubscribe_token : row[key])).join(','))].join('\r\n');
      return new Response(csv, { headers: { ...PRIVATE_HEADERS, 'Content-Type': 'text/csv;charset=UTF-8', 'Content-Disposition': 'attachment; filename="hi-signups.csv"' } });
    }
    if (url.pathname === '/unsubscribe') {
      if (request.method !== 'GET') return signupResponse({ error: 'Method not allowed' }, 405);
      const token = url.searchParams.get('t') || '';
      if (!/^[a-f0-9]{64}$/.test(token)) return signupResponse({ error: 'Invalid unsubscribe link' }, 400);
      const result = await env.SIGNUPS.prepare('UPDATE signups SET unsubscribed_at = COALESCE(unsubscribed_at, ?) WHERE unsubscribe_token = ?').bind(new Date().toISOString(), token).run();
      return new Response(result.meta.changes ? 'You are unsubscribed. You will receive no more letters.' : 'This unsubscribe link is not valid.', { status: result.meta.changes ? 200 : 404, headers: { ...PRIVATE_HEADERS, 'Content-Type': 'text/plain;charset=UTF-8' } });
    }
    if (request.method !== 'POST') return signupResponse({ error: 'Method not allowed' }, 405);
    if (request.headers.get('Origin') && request.headers.get('Origin') !== url.origin) return signupResponse({ error: 'Please sign up from this site.' }, 403);
    if (!env.SIGNUPS || !env.RATE_LIMIT_SALT) return signupResponse({ error: 'Signup temporarily unavailable. Please try again later.' }, 503);
    if (!(request.headers.get('Content-Type') || '').startsWith('application/json')) return signupResponse({ error: 'Expected JSON' }, 415);
    if (Number(request.headers.get('Content-Length')) > 4096) return signupResponse({ error: 'Submission too large' }, 413);
    const reader = request.body?.getReader();
    if (!reader) return signupResponse({ error: 'Empty submission' }, 400);
    let bytes = 0, chunks = [];
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      bytes += value.length;
      if (bytes > 4096) { await reader.cancel(); return signupResponse({ error: 'Submission too large' }, 413); }
      chunks.push(value);
    }
    let data;
    try { data = JSON.parse(await new Blob(chunks).text()); } catch { return signupResponse({ error: 'Invalid submission' }, 400); }
    if (!data || typeof data !== 'object' || Array.isArray(data)) return signupResponse({ error: 'Invalid submission' }, 400);
    if (data.website) return signupResponse({ ok: true });
    const ip = request.headers.get('CF-Connecting-IP');
    if (!ip) return signupResponse({ error: 'Signup temporarily unavailable.' }, 503);
    const hash = await signupHash(env.RATE_LIMIT_SALT + ':' + ip);
    const window = Math.floor(Date.now() / 3600000);
    const rate = await env.SIGNUPS.prepare('INSERT INTO signup_rate_limits (ip_hash, window, attempts) VALUES (?, ?, 1) ON CONFLICT(ip_hash) DO UPDATE SET attempts = CASE WHEN window = excluded.window THEN attempts + 1 ELSE 1 END, window = excluded.window RETURNING attempts').bind(hash, window).first();
    if (rate.attempts > 5) return signupResponse({ error: 'Too many attempts. Please try again in an hour.' }, 429, { 'Retry-After': '3600' });
    await env.SIGNUPS.prepare('DELETE FROM signup_rate_limits WHERE window < ?').bind(window - 24).run();
    const email = typeof data.email === 'string' ? data.email.trim().toLowerCase() : '';
    const interest = typeof data.interest === 'string' ? data.interest.trim() : '';
    const handle = typeof data.handle === 'string' ? data.handle.trim().replace(/^@/, '') : '';
    if (email.length > 254 || !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(email)) return signupResponse({ error: 'Please enter a valid email address.' }, 400);
    if (interest.length > 200 || (handle && !/^[A-Za-z0-9_]{1,15}$/.test(handle))) return signupResponse({ error: 'Use at most 200 characters for your interest and a valid X handle.' }, 400);
    const source = typeof data.source_page === 'string' ? data.source_page.slice(0, 300) : '/';
    const utm = JSON.stringify(Object.fromEntries(Object.entries(data.utm || {}).filter(([k,v]) => /^utm_(source|medium|campaign|term|content)$/.test(k) && typeof v === 'string').map(([k,v]) => [k,v.slice(0,200)])));
    const referrer = typeof data.referrer === 'string' ? data.referrer.slice(0,500) : '';
    const token = crypto.randomUUID().replaceAll('-', '') + crypto.randomUUID().replaceAll('-', '');
    // Keep the first nonempty interest: unverified retries cannot erase or replace it.
    // Update other optional fields only when explicitly submitted.
    // Preserve unsubscribe state and the existing private token.
    const signupId = crypto.randomUUID();
    const statement = env.SIGNUPS.prepare('INSERT INTO signups (id,email,interest,handle,public_opt_in,consent_at,source_page,utm,referrer,unsubscribe_token) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(email) DO UPDATE SET interest = CASE WHEN ? AND length(excluded.interest) > 0 AND length(signups.interest) = 0 THEN excluded.interest ELSE signups.interest END, handle = CASE WHEN ? THEN excluded.handle ELSE signups.handle END, public_opt_in = CASE WHEN length(CASE WHEN ? THEN excluded.handle ELSE signups.handle END) = 0 THEN 0 WHEN ? THEN ? ELSE signups.public_opt_in END, consent_at = excluded.consent_at').bind(signupId,email,interest,handle,handle && data.public_opt_in === true ? 1 : 0,new Date().toISOString(),source,utm,referrer,token,typeof data.interest === 'string' ? 1 : 0,typeof data.handle === 'string' ? 1 : 0,typeof data.handle === 'string' ? 1 : 0,typeof data.public_opt_in === 'boolean' ? 1 : 0,data.public_opt_in === true ? 1 : 0);
    if (typeof welcomeEnabled === 'function' && welcomeEnabled(env,ctx,url.origin)) {
      await env.SIGNUPS.batch([statement,welcomeStatement(env,signupId)]);
      scheduleWelcome(env,ctx,signupId);
    } else { await statement.run(); }
    // Keep status, body and headers identical for new, duplicate and opted-out emails.
    // Unsubscribe URLs are available only to the owner export for inclusion in letters.
    return signupResponse({ ok: true });
  } catch {
    // Never log submitted fields or tokens.
    return signupResponse({ error: 'Signup temporarily unavailable. Please try again later.' }, 503);
  }
}

// Private interest signals. The generated INTEREST_ITEMS catalogue is the only allowlist.
async function handleInterest(request, env, ctx) {
  const url = new URL(request.url);
  if (!['/api/interest', '/api/interest/counts', '/admin/interest.csv'].includes(url.pathname)) return null;
  try {
    if (url.pathname === '/api/interest/counts') {
      if (request.method !== 'GET') return signupResponse({error:'Method not allowed'},405);
      const rows = await env.SIGNUPS.prepare("SELECT item_key, COUNT(*) AS total FROM interest_signals WHERE kind = 'want' GROUP BY item_key HAVING COUNT(*) >= 3").all();
      return signupResponse({counts:Object.fromEntries(rows.results.filter(row => Object.hasOwn(INTEREST_ITEMS,row.item_key)).map(row => [row.item_key,row.total]))});
    }
    if (url.pathname === '/admin/interest.csv') {
      if (request.method !== 'GET') return signupResponse({error:'Method not allowed'},405);
      if (!env.ADMIN_EXPORT_TOKEN || await signupHash(request.headers.get('Authorization') || '') !== await signupHash('Bearer '+env.ADMIN_EXPORT_TOKEN)) return signupResponse({error:'Unauthorized'},401);
      const rows = await env.SIGNUPS.prepare('SELECT id,item_key,kind,email,handle,letter_opt_in,consent_at,source_page,utm,referrer FROM interest_signals ORDER BY consent_at').all();
      const totals = await env.SIGNUPS.prepare("SELECT item_key, COUNT(*) AS total FROM interest_signals WHERE kind = 'want' GROUP BY item_key").all();
      const counts = Object.fromEntries(totals.results.map(row => [row.item_key,row.total]));
      const columns = ['id','item_key','kind','email','handle','letter_opt_in','consent_at','source_page','utm','referrer','want_signals','milestone','tweet_draft'];
      const csv = [columns.join(','),...rows.results.map(row => {
        const count = counts[row.item_key] || 0, milestone = [100,50,25,10].find(n => count >= n) || '';
        const entry = {...row,want_signals:count,milestone,tweet_draft:milestone ? count+' interest signals for '+INTEREST_ITEMS[row.item_key]+'. Who is building it? https://humanityinfrastructure.com/?ref=x-interest#'+row.item_key : ''};
        return columns.map(key => signupCsv(entry[key])).join(',');
      })].join('\r\n');
      return new Response(csv,{headers:{...PRIVATE_HEADERS,'Content-Type':'text/csv;charset=UTF-8','Content-Disposition':'attachment; filename="hi-interest.csv"'}});
    }
    if (request.method !== 'POST') return signupResponse({error:'Method not allowed'},405);
    if (request.headers.get('Origin') !== url.origin) return signupResponse({error:'Please send your signal from this site.'},403);
    if (!env.SIGNUPS || !env.RATE_LIMIT_SALT) return signupResponse({error:'Interest signals temporarily unavailable.'},503);
    if (!(request.headers.get('Content-Type') || '').startsWith('application/json')) return signupResponse({error:'Expected JSON'},415);
    if (Number(request.headers.get('Content-Length')) > 4096) return signupResponse({error:'Submission too large'},413);
    const reader=request.body?.getReader();if(!reader)return signupResponse({error:'Empty submission'},400);
    let size=0;const chunks=[];
    while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>4096){await reader.cancel();return signupResponse({error:'Submission too large'},413);}chunks.push(value);}
    let data;try{data=JSON.parse(await new Blob(chunks).text());}catch{return signupResponse({error:'Invalid submission'},400);}
    if(!data || typeof data!=='object' || Array.isArray(data))return signupResponse({error:'Invalid submission'},400);
    if(data.website)return signupResponse({ok:true});
    const ip=request.headers.get('CF-Connecting-IP');if(!ip)return signupResponse({error:'Interest signals temporarily unavailable.'},503);
    const hash=await signupHash(env.RATE_LIMIT_SALT+':'+ip), hour=Math.floor(Date.now()/3600000), day=Math.floor(Date.now()/86400000);
    // Same atomic table/key and five-attempt budget as /api/signup.
    const rate=await env.SIGNUPS.prepare('INSERT INTO signup_rate_limits (ip_hash, window, attempts) VALUES (?, ?, 1) ON CONFLICT(ip_hash) DO UPDATE SET attempts = CASE WHEN window = excluded.window THEN attempts + 1 ELSE 1 END, window = excluded.window RETURNING attempts').bind(hash,hour).first();
    if(rate.attempts>5)return signupResponse({error:'Too many attempts. Please try again in an hour.'},429,{'Retry-After':'3600'});
    await env.SIGNUPS.prepare('DELETE FROM signup_rate_limits WHERE window < ?').bind(hour-24).run();
    if(typeof data.item_key!=='string' || !Object.hasOwn(INTEREST_ITEMS,data.item_key) || !['want','building'].includes(data.kind))return signupResponse({error:'Choose a listed item and signal type.'},400);
    const email=typeof data.email==='string'?data.email.trim().toLowerCase():'';
    const handle=typeof data.handle==='string'?data.handle.trim().replace(/^@/,''):'';
    if(email && (email.length>254 || !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(email)))return signupResponse({error:'Please enter a valid email address or leave it blank.'},400);
    if(handle && !/^[A-Za-z0-9_]{1,15}$/.test(handle))return signupResponse({error:'Please enter a valid X handle or leave it blank.'},400);
    const optIn=data.letter_opt_in===true;
    if(optIn && !email)return signupResponse({error:'Enter an email for updates, or leave updates unchecked.'},400);
    const source=typeof data.source_page==='string'?data.source_page.slice(0,300):'/';
    const utm=JSON.stringify(Object.fromEntries(Object.entries(data.utm || {}).filter(([key,value])=>/^utm_(source|medium|campaign|term|content)$/.test(key) && typeof value==='string').map(([key,value])=>[key,value.slice(0,200)])));
    const referrer=typeof data.referrer==='string'?data.referrer.slice(0,500):'', now=new Date().toISOString();
    // First signal wins across both kinds for this item/IP/UTC day. Never disclose duplicates.
    const statements=[env.SIGNUPS.prepare('INSERT INTO interest_signals (id,item_key,kind,ip_hash,day,email,handle,letter_opt_in,consent_at,source_page,utm,referrer) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(item_key,ip_hash,day) DO NOTHING').bind(crypto.randomUUID(),data.item_key,data.kind,hash,day,email,handle,optIn?1:0,now,source,utm,referrer)];
    const signupId=crypto.randomUUID(), sendWelcome=typeof welcomeEnabled==='function' && welcomeEnabled(env,ctx,url.origin);
    if(optIn){
      const token=crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');
      // Explicit letter consent only; never re-enable an unsubscribed email or replace saved details.
      statements.push(env.SIGNUPS.prepare('INSERT INTO signups (id,email,interest,handle,public_opt_in,consent_at,source_page,utm,referrer,unsubscribe_token) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(email) DO UPDATE SET consent_at = excluded.consent_at').bind(signupId,email,INTEREST_ITEMS[data.item_key],handle,0,now,source,utm,referrer,token));
    }
    if(optIn && sendWelcome)statements.push(welcomeStatement(env,signupId));
    await env.SIGNUPS.batch(statements);
    if(optIn && sendWelcome)scheduleWelcome(env,ctx,signupId);
    return signupResponse({ok:true});
  } catch {return signupResponse({error:'Interest signals temporarily unavailable. Please try again later.'},503);}
}

export default {
  async fetch(request, env, ctx) { return handleRequest(request, env, ctx) }
}

async function handleRequest(request, env, ctx) {
  const url = new URL(request.url)
  const path = url.pathname
  const signup = await handleSignup(request, env, ctx)
  if (signup) return signup
  if (path === '/analytics.js') return new Response(ANALYTICS_JS, { headers: { 'Content-Type': 'application/javascript;charset=UTF-8', 'Cache-Control': 'public, max-age=300' } })
  const interest = await handleInterest(request, env, ctx)
  if (interest) return interest
  if (path === '/interest-ui.js') return new Response(INTEREST_UI, { headers: { 'Content-Type': 'application/javascript;charset=UTF-8', 'Cache-Control': 'no-store' } })
  if (path === '/designs') return Response.redirect(url.origin + '/designs/', 302)
  if (path.startsWith('/designs/')) {
    const key = path.endsWith('/') ? path + 'index.html' : path
    const asset = DESIGN_ASSETS[key]
    const headers = {
      'X-Robots-Tag': 'noindex, nofollow, noarchive',
      'Cache-Control': 'public, no-transform',
      'Referrer-Policy': 'no-referrer',
      'X-Content-Type-Options': 'nosniff',
      'Content-Security-Policy': "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'none'; form-action 'none'; frame-ancestors 'self'; base-uri 'none'"
    }
    if (!asset) return new Response('Design not found', {status: 404, headers})
    headers['Content-Type'] = asset[0] + (asset[0].startsWith('text/') ? ';charset=UTF-8' : '')
    return new Response(Uint8Array.from(atob(asset[1]), c => c.charCodeAt(0)), {headers})
  }
  if (path === '/x-embed.js') return new Response(X_EMBED_JS, {headers: {'Content-Type': 'application/javascript;charset=UTF-8'}})
  if (path === '/og-card.png') {
    return new Response(OG_PNG, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400' } })
  }
  if (path === '/tools/lastbook' || path === '/tools/lastbook/') return new Response(LASTBOOK_HTML, {headers: {'Content-Type':'text/html;charset=UTF-8'}})
  if (path === '/classic' || path.startsWith('/classic/')) {
    return new Response(CLASSIC_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, no-transform', 'Content-Security-Policy': "script-src 'self' 'unsafe-inline' https://analytics.ideaflow.app; connect-src 'self' https://api.worldissuetracker.com https://analytics.ideaflow.app; object-src 'none'; base-uri 'self'" } })
  }
  if (path === '/v4' || path.startsWith('/v4/')) {
    return new Response(ARCHIVE_V4_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, no-transform', 'Content-Security-Policy': "script-src 'self' 'unsafe-inline' https://analytics.ideaflow.app; connect-src 'self' https://api.worldissuetracker.com https://analytics.ideaflow.app; object-src 'none'; base-uri 'self'" } })
  }
  if (path === '/v2' || path.startsWith('/v2/')) {
    return new Response(V2_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, no-transform', 'Content-Security-Policy': "script-src 'self' 'unsafe-inline' https://analytics.ideaflow.app; connect-src 'self' https://api.worldissuetracker.com https://analytics.ideaflow.app; object-src 'none'; base-uri 'self'" } })
  }
  if (path === '/v3' || path.startsWith('/v3/')) {
    return new Response(V3_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, no-transform', 'Content-Security-Policy': "script-src 'self' 'unsafe-inline' https://analytics.ideaflow.app; connect-src 'self' https://api.worldissuetracker.com https://analytics.ideaflow.app; object-src 'none'; base-uri 'self'" } })
  }
  if (path === '/v1' || path.startsWith('/v1/')) {
    return Response.redirect('https://humanityinfrastructure.com/', 301)
  }
  return new Response(MAIN_HTML, { headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, no-transform', 'Content-Security-Policy': "script-src 'self' 'unsafe-inline' https://analytics.ideaflow.app; connect-src 'self' https://api.worldissuetracker.com https://analytics.ideaflow.app; frame-src 'none'; object-src 'none'; base-uri 'self'" } })
}

const ANALYTICS_JS = `// Anonymous, cookieless analytics. Never pass form values or arbitrary URLs.
(function () {
  'use strict';
  const routes = new Set(['/', '/classic', '/v2', '/v3', '/v4', '/join']);
  const sources = new Set(['x', 'twitter', 'buzz', 'hi_newsletter', 'github', 'lastbook', 'x-interest']);
  function safeUrl(raw) {
    const url = new URL(raw || '/', location.origin);
    const path = routes.has(url.pathname.replace(/\\/$/, '') || '/') ? (url.pathname.replace(/\\/$/, '') || '/') : '/other';
    const query = new URLSearchParams();
    for (const key of ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'ref']) {
      const value = url.searchParams.get(key) || '';
      const valid = key === 'utm_source' || key === 'ref' ? sources.has(value)
        : key === 'utm_medium' ? ['social', 'community', 'email', 'referral'].includes(value)
        : key === 'utm_campaign' ? /^hi_launch_\\d{6}$/.test(value)
        : /^(reply_(farbood|kevinrose)_\\d{2}|launch_post_\\d{2}|issue_\\d{8}_primary)$/.test(value);
      if (valid) query.set(key, value);
    }
    return path + (query.size ? '?' + query : '');
  }
  window.hiAnalyticsBeforeSend = function (type, payload) {
    if (navigator.doNotTrack === '1' || navigator.doNotTrack === 'yes' || window.doNotTrack === '1') return null;
    // No tracking on private routes or previews; normal pageviews stay automatic.
    if (!['humanityinfrastructure.com', 'www.humanityinfrastructure.com', 'humanity3.earth'].includes(location.hostname)) return null;
    payload.url = safeUrl(payload.url);
    try { payload.referrer = payload.referrer ? new URL(payload.referrer, location.origin).origin : ''; }
    catch { payload.referrer = ''; }
    payload.title = 'Humanity Infrastructure';
    return payload;
  };
  const pending = [];
  // Before the wrapper arrives, window.ideaflow can be the <article id="ideaflow"> listing
  // (named element access), so require a real tracker, not just a truthy value.
  function tracker() {
    const t = window.ideaflow;
    return t && typeof t.track === 'function' ? t : null;
  }
  window.hiTrack = function (name, properties = {}) {
    if (navigator.doNotTrack === '1' || navigator.doNotTrack === 'yes') return;
    const t = tracker();
    if (t) t.track(name, properties);
    else if (pending.length < 30) pending.push([name, properties]);
  };
  // The shared wrapper loads async, so it may arrive after DOMContentLoaded: flush on both.
  function flush() {
    const t = tracker();
    if (t) pending.splice(0).forEach(([name, props]) => t.track(name, props));
  }
  window.hiAnalyticsFlush = flush;
  document.addEventListener('DOMContentLoaded', flush);
  document.addEventListener('click', function (event) {
    const target = event.target.closest('a[href], [data-signup-open]');
    if (!target || target.closest('#signal-thanks, #letter-context-links')) return;
    const placement = target.closest('footer') ? 'footer' : target.closest('header,nav') ? 'header' : 'body';
    if (target.matches('[data-signup-open]')) return window.hiTrack('newsletter_signup_start', {placement});
    const url = new URL(target.href, location.origin);
    const declared = target.dataset.analyticsEvent;
    if (['suggest_resource', 'pr_guide_open'].includes(declared)) return window.hiTrack(declared, {placement});
    if (!['http:', 'https:'].includes(url.protocol) || url.origin === location.origin) return;
    const host = url.hostname.replace(/^www\\./, '');
    const listing = target.closest('.tweet-card') ? null : target.dataset.analyticsListing || target.closest('.card[id]')?.id;
    const name = target.matches('.claim') ? 'quest_claim' : listing ? 'resource_outbound_click' : host === 'github.com' ? 'github_click' : ['x.com', 'twitter.com'].includes(host) ? 'x_outbound_click' : 'resource_outbound_click';
    const props = {placement, destination_host: host, elapsed_ms: Math.round(performance.now())};
    if (listing && /^[a-z0-9-]{1,80}$/.test(listing)) props.listing_id = listing;
    else if (host === 'lastbook.org') props.listing_id = 'lastbook';
    window.hiTrack(name, props);
  });
})();
`
